export default {"html":"<p data-line=\"0\" class=\"code-line\">Ionic Angular can now be used in a Standalone setup. That will change how I build apps going forward. Using <code>example.component.ts</code> as an example, the diff looks like this.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"2\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { CommonModule } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@angular/common'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { FormsModule } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@angular/forms'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonicModule, ModalController } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { ModalController } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular/standalone'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { addIcons } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'ionicons'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  wineOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  receiptOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  timeOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  walletOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  fileTrayStackedOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  calendarOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  documentTextOutline,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'ionicons/icons'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonHeader,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonToolbar,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonButtons,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonButton,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonContent,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonText,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonList,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonItem,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonLabel,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonIcon,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonInput,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonListHeader,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonRadioGroup,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonRadio,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  IonNote,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular/standalone'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"></span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-move-bottle'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./move-bottle.page.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./move-bottle.page.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">  standalone: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span style=\"color:#E1E4E8\">  imports: [IonicModule, FormsModule, CommonModule, KeyTrackByPipe],</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#E1E4E8\">  imports: [</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    FormsModule,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    CommonModule,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    KeyTrackByPipe,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonHeader,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonToolbar,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonButtons,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonButton,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonContent,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonText,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonList,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonItem,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonLabel,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonIcon,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonInput,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonListHeader,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonRadioGroup,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonRadio,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">    IonNote,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">  ],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#F97583\"> implements</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span style=\"color:#F97583\"></span><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {}</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#B392F0\">   addIcons</span><span style=\"color:#E1E4E8\">({ wineOutline, receiptOutline, timeOutline, walletOutline, fileTrayStackedOutline, calendarOutline, documentTextOutline });</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"70\" class=\"code-line\">Long, right? With this many lines, using Ionic components feels tedious. There was feedback on that in an issue— I read through it below.</p>\n<h2 id=\"feat%3A-ionic-angular-standalone-component-feedback-%2328445\" data-line=\"72\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#feat%3A-ionic-angular-standalone-component-feedback-%2328445\" aria-hidden=\"true\"></a> feat: Ionic Angular standalone component feedback #28445</h2>\n<p data-line=\"74\" class=\"code-line\">The most useful starting point for best practices is this issue on the Ionic Framework repository. In short: developer experience got worse.</p>\n<p data-line=\"76\" class=\"code-line\"><a href=\"https://github.com/ionic-team/ionic-framework/issues/28445\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/ionic-team/ionic-framework/issues/28445</a><a href=\"https://github.com/ionic-team/ionic-framework/issues/28445\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/ionic-team/ionic-framework/issues/28445</a></p>\n<p data-line=\"78\" class=\"code-line\">※ The issue mentions a v7.5.2 bug where Standalone increased bundle size; that is fixed, so I omit it here.</p>\n<blockquote data-line=\"81\" class=\"code-line\">\n<p data-line=\"81\" class=\"code-line\">Ionic does not provide export groups for components</p>\n</blockquote>\n<p data-line=\"83\" class=\"code-line\">If importing many Ionic components hurts DX, the first idea is component groups like this.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"85\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonAccordion, IonAccordionGroup, IonInput, IonTextarea } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular/standalone'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> const</span><span style=\"color:#79B8FF\"> ACCORDION_GROUP</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> [IonAccordion, IonAccordionGroup];</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> const</span><span style=\"color:#79B8FF\"> INPUT_GROUP</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> [IonInput, IonTextarea];</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"92\" class=\"code-line\">Like an NgModule you define yourself. But two problems appear. First, <code>ACCORDION_GROUP</code> has a clear scope, but <code>TOOLBAR_GROUP</code> raises subjective questions— does it include <code>IonTitle</code>? <code>IonButtons</code>?? Classification becomes subjective and cannot follow function. That does not improve DX. Second, IDE autocomplete does not surface component groups.</p>\n<p data-line=\"94\" class=\"code-line\"><img src=\"/images/d6b6c32a1f9d84/ide.png\" alt=\"\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"96\" class=\"code-line\">On a team, some developers import from groups and others from the package directly. This approach is not realistic.</p>\n<blockquote data-line=\"98\" class=\"code-line\">\n<p data-line=\"98\" class=\"code-line\">You don't have to call addIcons in every component.</p>\n<p data-line=\"100\" class=\"code-line\">You're more than welcome to register them in main.ts or app.component.ts.</p>\n</blockquote>\n<p data-line=\"102\" class=\"code-line\">The \"correct\" way to use IonIcon is to call <code>addIcons</code> for icons used in that component. Strictly speaking, <code>addIcons</code> registers icons on the window object. When IonIcon renders, it reads the window to find the icon. So if <code>addIcons</code> ran before IonIcon displays, the icon can show.</p>\n<p data-line=\"104\" class=\"code-line\">Example: use <code>CloseOutline</code> (<code>name=close-outline</code>) on both page A and page B. Page A always appears before page B.</p>\n<blockquote data-line=\"106\" class=\"code-line\">\n<p data-line=\"106\" class=\"code-line\">Page A → navigate → Page B</p>\n</blockquote>\n<p data-line=\"108\" class=\"code-line\">If only page B calls <code>addIcons(CloseOutline)</code>, page A shows no icon and page B does. If only page A calls it, both pages show the icon.</p>\n<p data-line=\"110\" class=\"code-line\">※ Strictly, lazy loading of page B and whether <code>constructor</code> runs from prefetch matter, but I omit that.</p>\n<p data-line=\"112\" class=\"code-line\">So registering icons in <code>main.ts</code> or <code>app.component.ts</code>, which run before components display, is valid. Note that more icons registered there increase initial bundle size.</p>\n<h2 id=\"how-to-approach-it\" data-line=\"114\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#how-to-approach-it\" aria-hidden=\"true\"></a> How to approach it</h2>\n<h3 id=\"ionic-components-import\" data-line=\"116\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ionic-components-import\" aria-hidden=\"true\"></a> Ionic Components import</h3>\n<p data-line=\"118\" class=\"code-line\">React, which has imported components individually from early on, is a good reference.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"120\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> React </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'react'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonContent, IonHeader, IonPage, IonTitle, IonToolbar } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/react'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> ExploreContainer </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '../components/ExploreContainer'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#9ECBFF\"> './Home.css'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#B392F0\"> Home</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> React</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">FC</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> (</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#79B8FF\">IonPage</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#79B8FF\">IonHeader</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#79B8FF\">IonToolbar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          &lt;</span><span style=\"color:#79B8FF\">IonTitle</span><span style=\"color:#E1E4E8\">&gt;Blank&lt;/</span><span style=\"color:#79B8FF\">IonTitle</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;/</span><span style=\"color:#79B8FF\">IonToolbar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">...</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"136\" class=\"code-line\">I asked people used to React: component groups are technically possible but a bad idea. IDE completion would diverge across authors and code would not stay consistent. React tried groups and moved to direct imports.</p>\n<p data-line=\"138\" class=\"code-line\">Unlike React, Angular components carry Custom Element loaders, so importing everything at once adds network load beyond bundle size. Importing only what you need is realistic.</p>\n<p data-line=\"140\" class=\"code-line\">To offset long import lists, you can move logic to a ViewModel. A simple example:</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">example.component.ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"142\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-settings'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./settings.page.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./settings.page.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  standalone: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  imports: [</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    RouterLink,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    FormsModule,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    CommonModule,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonRouterLink,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonHeader,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonToolbar,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonTitle,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonContent,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonRefresher,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonRefresherContent,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonList,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonListHeader,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonLabel,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonItem,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonIcon,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonToggle,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonButton,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonNote,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    IonText,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  ],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> SettingsPage</span><span style=\"color:#F97583\"> implements</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#B392F0\">OnDestroy</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ロジックを書くViewModelを呼び出し</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#FFAB70\"> vm</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> ViewModel</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // あとライフサイクルだけ書く</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#B392F0\"> ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.vm.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#B392F0\"> ngOnDestroy</span><span style=\"color:#E1E4E8\">() {}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">example.component.view-model.ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"182\"><span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> ViewModel</span><span style=\"color:#F97583\"> extends</span><span style=\"color:#B392F0\"> StoreModel</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#FFAB70\"> useShopMenu</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> boolean</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#F97583\"> readonly</span><span style=\"color:#FFAB70\"> helper</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HelperService);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#F97583\"> readonly</span><span style=\"color:#FFAB70\"> storage</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(StorageService);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#B392F0\"> initialize</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.helper.</span><span style=\"color:#B392F0\">setDefaultThemeMode</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.storage.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(StorageKeyEnum.useShopMenu).</span><span style=\"color:#B392F0\">then</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">useShopMenu</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      if</span><span style=\"color:#E1E4E8\"> (useShopMenu </span><span style=\"color:#F97583\">!==</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        this</span><span style=\"color:#E1E4E8\">.useShopMenu </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> useShopMenu;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#B392F0\"> doRefresh</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> RefresherCustomEvent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    event.target.</span><span style=\"color:#B392F0\">complete</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#B392F0\"> changeTheme</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">isDark</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> boolean</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.helper.</span><span style=\"color:#B392F0\">changeTheme</span><span style=\"color:#E1E4E8\">(isDark);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"207\" class=\"code-line\">This keeps the component as a shell for imports and lifecycle while logic lives elsewhere. You can also keep both in one file if you prefer— class line count does not necessarily grow.</p>\n<h3 id=\"ionicon\" data-line=\"209\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ionicon\" aria-hidden=\"true\"></a> IonIcon</h3>\n<p data-line=\"211\" class=\"code-line\">IonIcon is a bit different. Ideally you <code>addIcons</code> per component for only what you need. But <code>addIcons</code> is not tied to the build, so forgetting it does not fail the build— users may use an app with missing icons. The issue mentions this too; in practice you only get <code>console.error</code> in the browser, which is not enough.</p>\n<p data-line=\"213\" class=\"code-line\">Even when icons seem to work,</p>\n<blockquote data-line=\"215\" class=\"code-line\">\n<p data-line=\"215\" class=\"code-line\">Page A → navigate → Page B</p>\n</blockquote>\n<p data-line=\"217\" class=\"code-line\">as above, display order may hide missing registrations. Another navigation path might show page B first and break icons. So I built this CLI to collect icons automatically:</p>\n<p data-line=\"219\" class=\"code-line\"><a href=\"https://github.com/rdlabo-dev/ionic-angular-collect-icons\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/rdlabo-dev/ionic-angular-collect-icons</a><a href=\"https://github.com/rdlabo-dev/ionic-angular-collect-icons\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/rdlabo-dev/ionic-angular-collect-icons</a></p>\n<p data-line=\"221\" class=\"code-line\">It deduplicates icons from Ionic Angular components and <strong>calls <code>addIcons</code> in <code>main.ts</code></strong>. Because it does not call <code>addIcons</code> per component, it is not the \"correct\" practice— it is the practical approach I use.</p>\n<p data-line=\"223\" class=\"code-line\">The library auto-generates and updates files like this:</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">use-icons.ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"225\"><span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#E1E4E8\"> { keypadOutline, closeOutline, removeCircleOutline, addCircleOutline, arrowUpOutline, copyOutline, clipboardOutline, filterOutline, swapVerticalOutline, chevronDownOutline, imageOutline, documentOutline, add, wineOutline, receiptOutline, timeOutline, walletOutline, fileTrayStackedOutline, calendarOutline, documentTextOutline, logoApple, languageOutline, closeCircleOutline, pricetagOutline, arrowForwardOutline, cloudDownloadOutline, cloudUploadOutline, checkboxOutline, linkOutline, personCircleOutline, toggleOutline, printOutline, moon, fileTrayFullOutline, bagHandleOutline, codeWorkingOutline, analyticsOutline, trendingUpOutline, codeDownloadOutline, todayOutline, logoTwitter, readerOutline, checkmarkCircle, personOutline, ellipseOutline, locationOutline, listCircleOutline, barcodeOutline, albumsOutline, ellipsisHorizontalCircleOutline, addOutline, ellipsisHorizontalOutline, image, informationCircleOutline, earthOutline, bagCheckOutline, radioButtonOnOutline, exitOutline, trashOutline, swapHorizontal, alertCircle, home, paw, bagOutline, pinOutline, homeOutline, timerOutline, checkmarkCircleOutline, alertCircleOutline, settingsOutline, playOutline, arrowRedoOutline, briefcaseOutline, carOutline, gitCompareOutline } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> \"ionicons/icons\"</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"229\" class=\"code-line\">It scans project templates and collects only icons in use. Then <code>main.ts</code> calls <code>addIcons</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"231\"><span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span> import { addIcons } from 'ionicons';</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span> import * as allIcons from 'ionicons/icons';</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span> import * as useIcons from '../use-icons';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span> if (environment.production) {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   enableProdMode();</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span> }</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>  addIcons(environment.production ? useIcons : allIcons);</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"243\" class=\"code-line\"><code>environment.production</code> branches because without running the CLI the export list stays stale— in development I register <strong>all</strong> icons for better DX. That inflates bundle size, so production uses only icons from <code>use-icons.ts</code>. One command runs it— try it when you can.</p>\n<p data-line=\"245\" class=\"code-line\"><a href=\"https://github.com/rdlabo-dev/ionic-angular-collect-icons\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/rdlabo-dev/ionic-angular-collect-icons</a><a href=\"https://github.com/rdlabo-dev/ionic-angular-collect-icons\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/rdlabo-dev/ionic-angular-collect-icons</a></p>\n<p data-line=\"247\" class=\"code-line\">For now, this feels like the practical path.</p>\n<h2 id=\"summary\" data-line=\"249\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"251\" class=\"code-line\">I explored best practices for Ionic Angular Standalone. Standalone will change development a lot, so thinking about practices early improves DX. Do not postpone— consider it now.</p>\n<p data-line=\"253\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"feat%3A-ionic-angular-standalone-component-feedback-%2328445","text":"feat: Ionic Angular standalone component feedback #28445","level":2},{"id":"how-to-approach-it","text":"How to approach it","level":2},{"id":"ionic-components-import","text":"Ionic Components import","level":3},{"id":"ionicon","text":"IonIcon","level":3},{"id":"summary","text":"Summary","level":2}]} as const;
